// GANTI API key sesuai keinginan (harus sama dengan API_KEY di dashboard.html)
flow.set('apiKey', 'iot-kampus-2026');
flow.set('threshold', 30);
flow.set('alertActive', false);
return msg;

let d = msg.payload;
if (typeof d !== 'object' || d === null || d.suhu === undefined) return null;
const max = flow.get('threshold');
d.received = new Date().toISOString();
d.threshold = max;
d.alert = d.suhu > max;
flow.set('lastSensor', d);

const wasOver = flow.get('alertActive') || false;
flow.set('alertActive', d.alert);

// Output 1: simpan ke SQLite | Output 2: broadcast WebSocket | Output 3: notifikasi MQTT
const toDb = {topic:'', params:{$suhu:d.suhu, $kelembaban:d.kelembaban, $timestamp:d.timestamp, $received:d.received}};
const toWs = [{payload:{type:'sensor', data:d}}];
let toMqtt = null;
if (d.alert && !wasOver) {   // notifikasi hanya saat suhu BARU melewati batas
  const alert = {type:'alert', message:'Suhu ' + d.suhu + ' C melewati batas ' + max + ' C',
                 suhu:d.suhu, threshold:max, time:d.received};
  flow.set('lastAlert', alert);
  toWs.push({payload:alert});
  toMqtt = {topic:'iot/notifikasi', payload:alert};
  node.warn(alert.message);
}
return [toDb, toWs, toMqtt];

const H = {'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, POST, PUT, OPTIONS','Access-Control-Allow-Headers':'Content-Type, X-API-Key'};
msg.headers = H;
if (msg.req.headers['x-api-key'] !== flow.get('apiKey')) {
  msg.statusCode = 401;
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada'};
  return msg;
}
msg.statusCode = 200;
msg.payload = {
  status: 'success',
  data: flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null},
  threshold: flow.get('threshold'),
  server_time: new Date().toISOString()
};
return msg;

const H = {'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, POST, PUT, OPTIONS','Access-Control-Allow-Headers':'Content-Type, X-API-Key'};
msg.headers = H;
if (msg.req.headers['x-api-key'] !== flow.get('apiKey')) {
  msg.statusCode = 401;
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada'};
  return [null, msg];
}
let n = parseInt(msg.req.query.limit) || 50;      // default 50 data terakhir
n = Math.min(Math.max(n, 1), 500);
msg.params = {$limit: n};
return [msg, null];

const rows = (msg.payload || []).reverse();   // urut lama -> baru
msg.statusCode = 200;
msg.payload = {status:'success', count: rows.length, data: rows};
return msg;

const H = {'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, POST, PUT, OPTIONS','Access-Control-Allow-Headers':'Content-Type, X-API-Key'};
msg.headers = H;
if (msg.req.headers['x-api-key'] !== flow.get('apiKey')) {
  msg.statusCode = 401;
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada'};
  return msg;
}
msg.statusCode = 200;
msg.payload = {status:'success', max: flow.get('threshold'),
               alert_active: flow.get('alertActive') || false,
               last_alert: flow.get('lastAlert') || null};
return msg;

const H = {'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, POST, PUT, OPTIONS','Access-Control-Allow-Headers':'Content-Type, X-API-Key'};
msg.headers = H;
if (msg.req.headers['x-api-key'] !== flow.get('apiKey')) {
  msg.statusCode = 401;
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada'};
  return msg;
}
const raw = msg.payload ? msg.payload.max : undefined;
const v = Number(raw);
if (raw === undefined || raw === null || raw === '' || !isFinite(v) || v < -40 || v > 125) {
  msg.statusCode = 400;
  msg.payload = {status:'error', message:'Field "max" wajib berupa angka antara -40 dan 125'};
  return msg;
}
flow.set('threshold', v);
msg.statusCode = 200;
msg.payload = {status:'success', message:'Batas suhu diperbarui', max: v};
return msg;

const H = {'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, POST, PUT, OPTIONS','Access-Control-Allow-Headers':'Content-Type, X-API-Key'};
msg.headers = H;
if (msg.req.headers['x-api-key'] !== flow.get('apiKey')) {
  msg.statusCode = 401;
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada'};
  return [null, msg];
}
const body = msg.payload || {};
if (!body.device || !body.action) {
  msg.statusCode = 400;
  msg.payload = {status:'error', message:'device dan action wajib diisi'};
  return [null, msg];
}
if (!['on','off'].includes(body.action)) {
  msg.statusCode = 400;
  msg.payload = {status:'error', message:'action harus "on" atau "off"'};
  return [null, msg];
}
const mqttMsg = {topic:'iot/kontrol', payload:{device: body.device, action: body.action}};
msg.statusCode = 200;
msg.payload = {status:'success', message:'Perintah terkirim', sent: mqttMsg.payload};
return [mqttMsg, msg];

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;

